import { NextFunction, Request, Response } from 'express';
import {
  ConflictError,
  NotFoundError,
  ValidationError,
} from '../../domain/errors/DomainError';
import { InvalidRequestError } from '../http/RequestParser';

function statusFor(error: unknown): number {
  if (error instanceof ValidationError || error instanceof InvalidRequestError) return 400;
  if (error instanceof NotFoundError) return 404;
  if (error instanceof ConflictError) return 409;
  if (error instanceof SyntaxError) return 400; // malformed JSON body
  return 500;
}

export function errorHandler(
  error: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction,
): void {
  const status = statusFor(error);
  if (status === 500) {
    console.error(error);
  }
  const message =
    status === 500 || !(error instanceof Error) ? 'Internal server error' : error.message;
  res.status(status).json({ error: message });
}

